import copy
def solve7(g, trace=None):
    R,C=len(g),len(g[0])
    comps=components(g)
    comps.sort(key=lambda cs:-max(c for _,c in cs))
    out=[[0]*C for _ in range(R)]
    def touching(cells):
        return any(0<=r+dr<R and 0<=c+dc<C and out[r+dr][c+dc]!=0
                   for r,c in cells for dr,dc in((0,1),(0,-1),(1,0),(-1,0)))
    for cells in comps:
        col=g[cells[0][0]][cells[0][1]]
        if trace is not None: trace.append(('start',sorted(cells),col))
        seen={frozenset(cells)}
        for _ in range(40):
            while all(c+1<C for _,c in cells) and all(out[r][c+1]==0 for r,c in cells):
                cells=[(r,c+1) for r,c in cells]
            bs=any(c+1<C and out[r][c+1]!=0 for r,c in cells)
            if trace is not None: trace.append(('slid',sorted(cells),'bs',bs,'touch',touching(cells)))
            if not (bs or touching(cells)):
                break
            minc=min(c for _,c in cells); maxc=max(c for _,c in cells)
            mir=[(r, minc+(maxc-c)) for r,c in cells]
            if mir==cells or frozenset(mir) in seen or not all(out[r][c]==0 for r,c in mir):
                if trace is not None: trace.append(('nobreakmirror',sorted(mir)))
                break
            seen.add(frozenset(mir)); cells=mir
            if trace is not None: trace.append(('mir',sorted(cells)))
        for r,c in cells: out[r][c]=col
    return out
